+import { CueCardPanel, DEFAULT_CONFIG, formatDuration, type InterviewConfig, type PersonaKey, type RecognizedDraft, type RealtimeSubmitMode, type SpeechCaptureState } from "./shared";
+
+function formatMetaLabel(meta: AiRunMeta | null): string {
+  if (!meta) return "等待生成";
