import { ArrowRight, FileSearch, Sparkles } from "lucide-react";
import { FormEvent, useMemo, useState } from "react";
import { repairText } from "../lib/copy";
import type { CandidateProfile, Position, WorkspaceState } from "../types";

type JdChatMessage = {
  id: string;
  role: "assistant" | "user";
  text: string;
};

function buildJdReply(question: string, workspace: WorkspaceState | null, profile: CandidateProfile): string {
  const normalized = question.toLowerCase();
  if (!workspace) return "先创建一个岗位，我再围绕当前 JD 帮你拆解重点。";

  if (normalized.includes("更看重") || normalized.includes("重点")) {
    return `这个岗位当前最看重 ${workspace.job.hardSkills.slice(0, 3).join("、") || "核心业务理解"}，其次是 ${workspace.job.softSkills.slice(0, 2).join("、") || "表达与协作"}。你在回答时要把经历主动对齐到这些关键词。`;
  }
  if (normalized.includes("差距") || normalized.includes("最弱")) {
    const gap = workspace.matchReport.gaps.find((item) => item.type !== "match");
    return gap ? `你当前最明显的短板是“${gap.label}”。${gap.description}` : "目前没有特别突出的硬性短板，建议优先强化可量化结果和个人贡献边界。";
  }
  if (normalized.includes("高频题") || normalized.includes("5 道")) {
    return workspace.questions
      .slice(0, 5)
      .map((item, index) => `${index + 1}. ${repairText(item.question)}`)
      .join("\n");
  }
  if (normalized.includes("简历") || normalized.includes("证据")) {
    return `当前和这个 JD 最相关的简历证据包括：${profile.evidenceLibrary.slice(0, 3).map((item) => item.title).join("、")}。建议优先用这些经历回答项目深挖和专业技能题。`;
  }
  return "我建议你围绕岗位要求、个人证据和表达短板三个维度继续追问，例如“这个岗位最看重什么”“我最弱的是哪块”“给我 5 道高频题”。";
}

export function JdWorkspace({
  workspace,
  profile,
  position,
  onSubmitJd,
  onOpenLive,
  onOpenMock,
  onCreateQuestions,
}: {
  workspace: WorkspaceState | null;
  profile: CandidateProfile;
  position?: Position;
  onSubmitJd: (jobText: string) => void;
  onOpenLive: () => void;
  onOpenMock: () => void;
  onCreateQuestions: (items: Array<{ question: string; category: string; difficulty: string; notes?: string }>) => void;
}) {
  const [draft, setDraft] = useState(workspace?.jobText ?? "");
  const [chatInput, setChatInput] = useState("");
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [messages, setMessages] = useState<JdChatMessage[]>([
    { id: "jd-assistant-1", role: "assistant", text: "你可以问我：这个岗位更看重什么、我最弱的是哪块、给我 5 道高频题。" },
  ]);

  const insightGroups = useMemo(() => {
    if (!workspace) return [];
    return [
      { title: "简历差异", items: workspace.matchReport.gaps.slice(0, 5).map((item) => `${repairText(item.label)}：${repairText(item.description)}`), defaultOpen: true },
      { title: "核心技能", items: workspace.job.hardSkills.slice(0, 6), defaultOpen: false },
      { title: "软性要求", items: workspace.job.softSkills.slice(0, 6), defaultOpen: false },
      { title: "隐藏信号", items: workspace.job.hiddenSignals.slice(0, 6), defaultOpen: false },
    ];
  }, [workspace]);

  const keywords = workspace?.job.keywords.slice(0, 12) ?? [];
  const visibleKeywords = keywords.slice(0, 6);
  const hiddenKeywords = keywords.slice(6);

  const submitJd = (event: FormEvent) => {
    event.preventDefault();
    if (!draft.trim()) return;
    onSubmitJd(draft.trim());
  };

  const sendChat = (event: FormEvent) => {
    event.preventDefault();
    const question = chatInput.trim();
    if (!question) return;
    const reply = buildJdReply(question, workspace, profile);
    setMessages((current) => [
      ...current,
      { id: `jd-user-${current.length + 1}`, role: "user", text: question },
      { id: `jd-assistant-${current.length + 2}`, role: "assistant", text: reply },
    ]);
    setChatInput("");
  };

  const saveSuggestedQuestions = () => {
    if (!workspace) return;
    onCreateQuestions(
      workspace.questions.slice(0, 5).map((item) => ({
        question: item.question,
        category: item.category,
        difficulty: item.difficulty,
        notes: "来自 JD 分析页推荐问题。",
      })),
    );
  };

  return (
    <section className="page page-jd desktop-page">
      <header className="desktop-page-header">
        <div className="desktop-page-title">
          <span className="page-eyebrow">JD 分析</span>
          <h1>岗位分析</h1>
        </div>
        <div className="hero-actions">
          <button className="button secondary" type="button" onClick={() => setDrawerOpen(true)}>
            分析对话
          </button>
          <button className="button secondary" type="button" onClick={onOpenMock} disabled={!workspace}>
            模拟练习
          </button>
          <button className="button primary" type="button" onClick={onOpenLive} disabled={!workspace}>
            开启实时助手
            <ArrowRight size={16} />
          </button>
        </div>
      </header>

      <div className="two-column-layout jd-page-layout">
        <section className="surface-card jd-analysis-column">
          <div className="surface-card-inner">
            <div className="section-row-header">
              <div>
                <span className="subtle-label">分析结果</span>
                <h2>{position ? `${repairText(position.company)} · ${repairText(position.title)}` : "还没有岗位"}</h2>
              </div>
              <button className="button secondary" type="button" onClick={saveSuggestedQuestions} disabled={!workspace}>
                保存 5 道高频题
              </button>
            </div>

            {workspace ? (
              <div className="analysis-stack">
                <section className="analysis-panel">
                  <strong>关键词</strong>
                  <div className="pill-row">
                    {visibleKeywords.map((item) => (
                      <span key={item} className="pill">{repairText(item)}</span>
                    ))}
                  </div>
                  {hiddenKeywords.length > 0 ? (
                    <details className="keyword-inline-expand">
                      <summary>展开更多关键词</summary>
                      <div className="pill-row">
                        {hiddenKeywords.map((item) => (
                          <span key={item} className="pill">{repairText(item)}</span>
                        ))}
                      </div>
                    </details>
                  ) : null}
                </section>

                {insightGroups.map((group) => (
                  <details key={group.title} className="analysis-collapse" open={group.defaultOpen}>
                    <summary>{group.title}</summary>
                    <ul className="simple-list">
                      {group.items.length > 0 ? group.items.map((item) => <li key={item}>{repairText(item)}</li>) : <li>暂无数据</li>}
                    </ul>
                  </details>
                ))}

                <details className="analysis-collapse">
                  <summary>JD 原文</summary>
                  <form className="drawer-form inline-form" onSubmit={submitJd}>
                    <textarea
                      className="input textarea tall"
                      value={draft}
                      aria-label="JD 文本"
                      onChange={(event) => setDraft(event.target.value)}
                      placeholder="粘贴当前岗位 JD，更新后左侧分析会同步刷新。"
                    />
                    <div className="drawer-actions">
                      <button className="button primary" type="submit" disabled={!draft.trim()}>
                        更新分析
                      </button>
                    </div>
                  </form>
                </details>
              </div>
            ) : (
              <div className="empty-card compact">
                <div className="empty-card-icon">
                  <FileSearch size={18} />
                </div>
                <div>
                  <h2>先生成一个岗位卡</h2>
                  <p>有了当前岗位后，这里会展示 JD 关键词、要求分层、简历差异和推荐问题。</p>
                </div>
              </div>
            )}
          </div>
        </section>
      </div>

      {drawerOpen ? (
        <div className="drawer-backdrop" role="presentation" onClick={() => setDrawerOpen(false)}>
          <aside className="drawer-panel narrow" role="dialog" aria-modal="true" aria-label="岗位分析对话" onClick={(event) => event.stopPropagation()}>
            <header className="drawer-header">
              <div>
                <span className="page-eyebrow">分析对话</span>
                <h2>岗位分析助手</h2>
              </div>
              <span className="assistant-badge">
                <Sparkles size={14} />
                窄域助手
              </span>
            </header>

            <div className="chat-thread">
              {messages.map((message) => (
                <article key={message.id} className={message.role === "assistant" ? "chat-bubble assistant" : "chat-bubble user"}>
                  <p>{message.text}</p>
                </article>
              ))}
            </div>

            <form className="chat-composer" onSubmit={sendChat}>
              <textarea
                value={chatInput}
                aria-label="JD 对话输入"
                onChange={(event) => setChatInput(event.target.value)}
                placeholder="例如：这个岗位更看重什么？给我 5 道高频题。"
              />
              <button className="button primary" type="submit" disabled={!chatInput.trim()}>
                发送
              </button>
            </form>
          </aside>
        </div>
      ) : null}
    </section>
  );
}

import { FileUp, Plus, ScrollText } from "lucide-react";
import { ChangeEvent, FormEvent, useMemo, useState } from "react";
import { repairText } from "../lib/copy";
import { importResumeFile } from "../lib/resumeImport";
import type { InterviewQuestion, WorkspaceState } from "../types";

type ParsedUploadItem = {
  question: string;
  answer: string;
  notes: string;
};

function parseUploadToCandidates(text: string): ParsedUploadItem[] {
  const blocks = text
    .split(/\n{2,}/)
    .map((item) => item.trim())
    .filter(Boolean);

  return blocks.slice(0, 6).map((block, index) => {
    const lines = block.split("\n").map((line) => line.trim()).filter(Boolean);
    return {
      question: lines[0] || `候选问题 ${index + 1}`,
      answer: lines.slice(1, 3).join(" "),
      notes: lines.slice(3).join(" "),
    };
  });
}

export function QuestionsWorkspace({
  workspace,
  onUpdateQuestion,
  onAddQuestion,
  onOpenLive,
  onOpenMock,
}: {
  workspace: WorkspaceState | null;
  onUpdateQuestion: (questionId: string, patch: Partial<InterviewQuestion>) => void;
  onAddQuestion: (question: Pick<InterviewQuestion, "question" | "category" | "difficulty"> & { answer?: string; notes?: string }) => void;
  onOpenLive: () => void;
  onOpenMock: () => void;
}) {
  const [newQuestion, setNewQuestion] = useState("");
  const [newAnswer, setNewAnswer] = useState("");
  const [newNotes, setNewNotes] = useState("");
  const [category, setCategory] = useState<string>(workspace?.questions[0]?.category ?? "项目深挖");
  const [pendingUpload, setPendingUpload] = useState<ParsedUploadItem[]>([]);
  const [uploadMessage, setUploadMessage] = useState("");

  const grouped = useMemo(() => {
    const questions = workspace?.questions ?? [];
    return questions.reduce<Record<string, InterviewQuestion[]>>((acc, item) => {
      const key = repairText(item.category) || "未分类";
      acc[key] = [...(acc[key] ?? []), item];
      return acc;
    }, {});
  }, [workspace]);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!newQuestion.trim()) return;
    onAddQuestion({
      question: newQuestion.trim(),
      category,
      difficulty: "进阶",
      answer: newAnswer.trim(),
      notes: newNotes.trim(),
    });
    setNewQuestion("");
    setNewAnswer("");
    setNewNotes("");
  };

  const onFile = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const result = await importResumeFile(file);
      const candidates = parseUploadToCandidates(result.text);
      setPendingUpload(candidates);
      setUploadMessage(`已解析 ${file.name}，请确认要入库的问题。`);
    } catch {
      setUploadMessage("上传失败，当前支持 txt / markdown / pdf / docx。");
    } finally {
      event.target.value = "";
    }
  };

  const commitUpload = () => {
    pendingUpload.forEach((item) => {
      onAddQuestion({
        question: item.question,
        category: "项目深挖",
        difficulty: "进阶",
        answer: item.answer,
        notes: item.notes || "来自上传文件解析",
      });
    });
    setPendingUpload([]);
    setUploadMessage("候选问题已加入问题库。");
  };

  return (
    <section className="page page-questions">
      <header className="page-hero">
        <div className="page-hero-copy">
          <span className="page-eyebrow">问题库</span>
          <h1>把问题、答案和笔记沉淀成长期资产</h1>
          <p>支持手动保存、上传文档解析为候选条目、再确认入库。题库和实时助手、模拟面试之间保持双向沉淀。</p>
        </div>
        <div className="hero-actions">
          <button className="button secondary" type="button" onClick={onOpenMock} disabled={!workspace}>
            去模拟面试
          </button>
          <button className="button primary" type="button" onClick={onOpenLive} disabled={!workspace}>
            去实时助手
          </button>
        </div>
      </header>

      <div className="page-grid">
        <section className="surface-card">
          <div className="surface-card-inner">
            <div className="section-row-header">
              <div>
                <span className="subtle-label">手动新增</span>
                <h2>问题 / 答案 / 笔记</h2>
              </div>
            </div>

            <form className="question-form" onSubmit={submit}>
              <select className="input" value={category} onChange={(event) => setCategory(event.target.value)} aria-label="问题分类">
                {["行为面", "项目深挖", "专业技能", "岗位动机", "压力题", "英文题"].map((item) => (
                  <option key={item} value={item}>{item}</option>
                ))}
              </select>
              <textarea className="input textarea" value={newQuestion} aria-label="新增问题" onChange={(event) => setNewQuestion(event.target.value)} placeholder="输入问题，例如：请介绍一个你做过最有挑战性的产品功能。" />
              <textarea className="input textarea compact" value={newAnswer} aria-label="问题答案" onChange={(event) => setNewAnswer(event.target.value)} placeholder="可以先写参考答案。" />
              <textarea className="input textarea compact" value={newNotes} aria-label="问题笔记" onChange={(event) => setNewNotes(event.target.value)} placeholder="记录表达提醒、复盘笔记或后续补强点。" />
              <button className="button primary" type="submit" disabled={!newQuestion.trim()}>
                <Plus size={16} />
                保存到问题库
              </button>
            </form>
          </div>
        </section>

        <section className="surface-card">
          <div className="surface-card-inner">
            <div className="section-row-header">
              <div>
                <span className="subtle-label">文件导入</span>
                <h2>上传 Word / PDF</h2>
              </div>
            </div>

            <label className="upload-dropzone">
              <FileUp size={18} />
              <strong>上传文件并解析为候选问题</strong>
              <p>系统会先生成候选问题、参考答案和笔记，再由你确认入库。</p>
              <input type="file" accept=".txt,.md,.markdown,.pdf,.docx" aria-label="上传问题库文件" onChange={onFile} />
            </label>
            {uploadMessage ? <div className="inline-message success">{uploadMessage}</div> : null}

            {pendingUpload.length > 0 ? (
              <div className="candidate-upload-list">
                {pendingUpload.map((item, index) => (
                  <article key={`${item.question}-${index}`} className="candidate-upload-item">
                    <strong>{item.question}</strong>
                    <p>{item.answer || "暂无参考答案，建议入库后补充。"}</p>
                    <small>{item.notes || "暂无笔记"}</small>
                  </article>
                ))}
                <button className="button primary" type="button" onClick={commitUpload}>
                  确认入库
                </button>
              </div>
            ) : null}
          </div>
        </section>
      </div>

      <section className="surface-card">
        <div className="surface-card-inner">
          <div className="section-row-header">
            <div>
              <span className="subtle-label">已沉淀问题</span>
              <h2>按意图分类查看</h2>
            </div>
          </div>

          {workspace && Object.keys(grouped).length > 0 ? (
            <div className="question-groups">
              {Object.entries(grouped).map(([group, items]) => (
                <section key={group} className="question-group">
                  <header>
                    <strong>{group}</strong>
                    <span>{items.length} 题</span>
                  </header>
                  <div className="question-group-list">
                    {items.map((item) => (
                      <article key={item.id} className="question-bank-item">
                        <div className="question-bank-head">
                          <span className="status-chip muted">{repairText(item.difficulty)}</span>
                          {item.priority ? <span className="status-chip positive">高频</span> : null}
                          {item.source === "manual" ? <span className="status-chip">已收藏</span> : null}
                        </div>
                        <textarea className="input textarea compact" value={repairText(item.question)} aria-label={`${item.id} 题目`} onChange={(event) => onUpdateQuestion(item.id, { question: event.target.value })} />
                        <textarea className="input textarea compact" value={repairText(item.answer || "")} aria-label={`${item.id} 答案`} onChange={(event) => onUpdateQuestion(item.id, { answer: event.target.value })} placeholder="补充参考答案" />
                        <textarea className="input textarea compact" value={repairText(item.notes)} aria-label={`${item.id} 笔记`} onChange={(event) => onUpdateQuestion(item.id, { notes: event.target.value })} placeholder="记录笔记 / 复盘 / 追问提醒" />
                      </article>
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : (
            <div className="empty-card compact">
              <div className="empty-card-icon">
                <ScrollText size={18} />
              </div>
              <div>
                <h2>问题库还没有内容</h2>
                <p>可以从上方手动新增，或上传文档解析为候选问题后再确认入库。</p>
              </div>
            </div>
          )}
        </div>
      </section>
    </section>
  );
}

