                </button>
              </div>
            ) : null}
          </div>
        </section>

        <section className="surface-card">
          <div className="surface-card-inner">
            <div className="section-row-header">
              <div>
                <span className="subtle-label">已沉淀题目</span>
                <h2>按分类查看</h2>
              </div>
            </div>

            {workspace && groupEntries.length > 0 ? (
              <>
                <div className="question-tab-row" role="tablist" aria-label="问题分类">
                  {groupEntries.map(([group, items]) => (
                    <button
                      key={group}
                      type="button"
                      role="tab"
                      aria-selected={visibleGroup === group}
                      className={visibleGroup === group ? "question-tab active" : "question-tab"}
                      onClick={() => {
                        setActiveGroup(group);
                        setExpandedQuestionId("");
