                    >
                      {group}
                      <span>{items.length} 题</span>
                    </button>
                  ))}
                </div>

                <div className="question-groups">
                  {visibleQuestions.map((item) => {
                    const expanded = expandedQuestionId === item.id;
                    return (
                      <article key={item.id} className={expanded ? "question-bank-row expanded" : "question-bank-row"}>
                        <button type="button" className="question-bank-row-head" onClick={() => setExpandedQuestionId((current) => (current === item.id ? "" : item.id))}>
                          <div className="question-bank-head">
                            <span className="status-chip muted">{repairText(item.difficulty)}</span>
                            {item.priority ? <span className="status-chip positive">高频</span> : null}
                            {item.answer ? <span className="status-chip">已练习</span> : <span className="status-chip warn">未练习</span>}
                          </div>
                          <strong>{repairText(item.question)}</strong>
                        </button>

