import { ArrowRight, FileText, Upload } from "lucide-react";
import { ChangeEvent, FormEvent, useMemo, useState } from "react";
import { repairText } from "../lib/copy";
import { importResumeFile } from "../lib/resumeImport";
import type { CandidateProfile, EvidenceItem, Position } from "../types";
import { buildResumeSections, buildResumeSuggestion, makeId, resolveEvidenceType, sectionsToDrafts, type ResumeChatMessage, type ResumeSectionId } from "./shared";

export function ResumeWorkspacePage({
  profile,
  position,
  onUpdateResume,
  onUpdateEvidence,
  onSetHighlights,
  onOpenLive,
  onOpenJd,
}: {
  profile: CandidateProfile;
  position?: Position;
  onUpdateResume: (resumeText: string) => void;
  onUpdateEvidence: (items: EvidenceItem[]) => void;
  onSetHighlights: (highlights: string[]) => void;
  onOpenLive: () => void;
  onOpenJd: () => void;
}) {
  const sections = useMemo(() => buildResumeSections(profile), [profile]);
  const [selectedSectionId, setSelectedSectionId] = useState<ResumeSectionId>("highlights");
  const [sectionDrafts, setSectionDrafts] = useState<Record<ResumeSectionId, string>>(() => sectionsToDrafts(sections));
  const [chatInput, setChatInput] = useState("");
  const [fileMessage, setFileMessage] = useState("");
  const [chatMessages, setChatMessages] = useState<ResumeChatMessage[]>([
    { id: "resume-chat-1", role: "assistant", text: "选中左侧任一模块，我可以帮你润色、改写、提炼亮点，或按当前岗位给出匹配建议。" },
  ]);

  const selectedSection = sections.find((section) => section.id === selectedSectionId) ?? sections[0];

  const onFile = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const result = await importResumeFile(file);
      onUpdateResume(result.text);
      setFileMessage(`已导入 ${file.name}${result.warning ? `，${result.warning}` : ""}`);
    } catch {
      setFileMessage("导入失败，当前支持 txt / markdown / pdf / docx。");
    } finally {
      event.target.value = "";
    }
  };

  const saveSection = () => {
    const text = sectionDrafts[selectedSectionId].trim();
    if (!text) return;

    if (selectedSectionId === "highlights") {
      onSetHighlights(
        text
          .split(/\n+/)
          .map((item) => item.replace(/^[-\d.、\s]+/, "").trim())
          .filter(Boolean)
          .slice(0, 6),
      );
      return;
    }

    onUpdateEvidence([
      {
        id: makeId("ev-custom"),
        type: resolveEvidenceType(selectedSectionId),
        title: selectedSection.title,
        detail: text,
        keywords: [],
        impact: "从简历页手动沉淀的可复用素材",
      },
      ...profile.evidenceLibrary,
    ]);
  };

  const optimizeSection = () => {
    const suggestion = buildResumeSuggestion(selectedSection.title, sectionDrafts[selectedSectionId] || selectedSection.content, profile);
    setChatMessages((current) => [
      ...current,
      { id: makeId("resume-user"), role: "user", text: `优化「${selectedSection.title}」` },
      { id: makeId("resume-ai"), role: "assistant", text: "我整理了一版更适合投递和面试表达的写法，你可以先看再决定是否应用。", sectionId: selectedSectionId, suggestion },
    ]);
  };

  const sendChat = (event: FormEvent) => {
    event.preventDefault();
    const text = chatInput.trim();
    if (!text) return;
    const suggestion = buildResumeSuggestion(selectedSection.title, `${sectionDrafts[selectedSectionId]}\n${text}`, profile);
    setChatMessages((current) => [
      ...current,
      { id: makeId("resume-user"), role: "user", text },
      { id: makeId("resume-ai"), role: "assistant", text: "按你的要求，我生成了一版更聚焦岗位匹配和表达结果的版本。", sectionId: selectedSectionId, suggestion },
    ]);
    setChatInput("");
  };

  const applySuggestion = (message: ResumeChatMessage) => {
    if (!message.suggestion || !message.sectionId) return;
    setSelectedSectionId(message.sectionId);
    setSectionDrafts((current) => ({ ...current, [message.sectionId!]: message.suggestion! }));
  };

  return (
    <section className="page page-resume">
      <header className="page-hero">
        <div className="page-hero-copy">
          <span className="page-eyebrow">简历</span>
          <h1>把简历维护、优化和岗位匹配分析放回一个专门页面</h1>
          <p>左侧管模块，中间做编辑，右侧看 AI 优化与岗位匹配建议。简历证据会继续作为实时助手和模拟面试的底层资料。</p>
        </div>
        <div className="hero-actions">
          <button className="button secondary" type="button" onClick={onOpenJd}>
            去 JD 分析
          </button>
          <button className="button primary" type="button" onClick={onOpenLive} disabled={!position}>
            去实时助手
            <ArrowRight size={16} />
          </button>
        </div>
      </header>

      <div className="resume-layout">
        <aside className="surface-card resume-nav-column">
          <div className="surface-card-inner">
            <div className="section-row-header">
              <div>
                <span className="subtle-label">模块导航</span>
                <h2>我的简历</h2>
              </div>
            </div>

            <div className="resume-nav-list">
              {sections.map((section) => (
                <button
                  key={section.id}
                  type="button"
                  className={selectedSectionId === section.id ? "resume-nav-item active" : "resume-nav-item"}
                  onClick={() => setSelectedSectionId(section.id)}
                >
                  <section.icon size={16} />
                  <span>{section.title}</span>
                </button>
              ))}
            </div>

            <label className="upload-dropzone compact">
              <Upload size={18} />
              <strong>上传简历文件</strong>
              <p>支持 Word / PDF，导入后会更新当前简历内容。</p>
              <input type="file" accept=".txt,.md,.markdown,.pdf,.docx" aria-label="上传简历文件" onChange={onFile} />
            </label>
            {fileMessage ? <div className="inline-message success">{fileMessage}</div> : null}
          </div>
        </aside>

        <main className="surface-card resume-editor-column">
          <div className="surface-card-inner">
            <div className="resume-profile-head">
              <div className="resume-avatar">{(profile.displayName || profile.resume.name || "候").slice(0, 1)}</div>
              <div>
                <strong>{repairText(profile.displayName || profile.resume.name || "候选人")}</strong>
                <p>{repairText(profile.resume.targetRole)}{position ? ` · 当前目标：${repairText(position.title)}` : ""}</p>
              </div>
            </div>

            <div className="section-row-header">
              <div>
                <span className="subtle-label">{selectedSection.label}</span>
                <h2>{selectedSection.title}</h2>
              </div>
              <div className="hero-actions">
                <button className="button secondary" type="button" onClick={optimizeSection}>
                  模块优化
                </button>
                <button className="button primary" type="button" onClick={saveSection}>
                  保存素材
                </button>
              </div>
            </div>

            <textarea
              className="input textarea tall"
              value={sectionDrafts[selectedSectionId]}
              aria-label={`${selectedSection.title} 编辑`}
              onChange={(event) => setSectionDrafts((current) => ({ ...current, [selectedSectionId]: event.target.value }))}
            />

            <div className="resume-module-grid">
              {sections.map((section) => (
                <article key={section.id} className={selectedSectionId === section.id ? "resume-module-card active" : "resume-module-card"} onClick={() => setSelectedSectionId(section.id)}>
                  <span>{section.label}</span>
                  <strong>{section.title}</strong>
                  <p>{repairText(section.content).slice(0, 120) || "等待补充内容"}</p>
                </article>
              ))}
            </div>
          </div>
        </main>

        <aside className="surface-card resume-ai-column">
          <div className="surface-card-inner">
            <div className="section-row-header">
              <div>
                <span className="subtle-label">AI 优化与分析</span>
                <h2>当前模块：{selectedSection.title}</h2>
              </div>
            </div>

            <div className="hero-inline-links stacked">
              <button className="mini-link" type="button" onClick={optimizeSection}>
                <FileText size={16} />
                模块级优化
              </button>
              <button
                className="mini-link"
                type="button"
                onClick={() =>
                  setChatMessages((current) => [
                    ...current,
                    {
                      id: makeId("resume-ai"),
                      role: "assistant",
                      text: "我基于整份简历整理了一版更适合岗位投递的整体优化建议。",
                      sectionId: selectedSectionId,
                      suggestion: buildResumeSuggestion("整份简历", profile.resumeText, profile),
                    },
                  ])
                }
              >
                <FileText size={16} />
                整份优化
              </button>
              <button
                className="mini-link"
                type="button"
                onClick={() =>
                  setChatMessages((current) => [
                    ...current,
                    {
                      id: makeId("resume-ai"),
                      role: "assistant",
                      text: position
                        ? `当前岗位“${repairText(position.title)}”更看重 ${position.job.hardSkills.slice(0, 3).join("、") || "核心能力"}，建议在当前模块补足对应证据。`
                        : "还没有当前岗位，先去岗位台或 JD 分析页选择一个岗位。",
                    },
                  ])
                }
              >
                <FileText size={16} />
                匹配分析
              </button>
            </div>

            <div className="chat-thread resume-chat-thread">
              {chatMessages.map((message) => (
                <article key={message.id} className={message.role === "assistant" ? "chat-bubble assistant" : "chat-bubble user"}>
                  <p>{message.text}</p>
                  {message.suggestion ? (
                    <div className="suggestion-box">
                      <pre>{message.suggestion}</pre>
                      <button className="button primary" type="button" onClick={() => applySuggestion(message)}>
                        应用到当前模块
                      </button>
                    </div>
                  ) : null}
                </article>
              ))}
            </div>

            <form className="chat-composer" onSubmit={sendChat}>
              <textarea
                value={chatInput}
                aria-label="简历优化需求"
                onChange={(event) => setChatInput(event.target.value)}
                placeholder="例如：把这段项目经历改得更像产品岗、帮我补强结果表达、按当前岗位重写亮点。"
              />
              <button className="button primary" type="submit" disabled={!chatInput.trim()}>
                发送
              </button>
            </form>
          </div>
        </aside>
      </div>
    </section>
  );
}

