type RecordsFilterMode = "all" | "live" | "mock";

function formatRecordTime(value: string): string {
  return new Date(value).toLocaleString("zh-CN", {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export function RecordsView({
  records,
  positions,
  onOpen,
  onMock,
}: {
  records: InterviewRecord[];
  positions: Position[];
  onOpen: (id: string) => void;
  onMock: () => void;
}) {
  const [mode, setMode] = useState<RecordsFilterMode>("all");
  const [positionId, setPositionId] = useState("all");

  const filtered = useMemo(
    () =>
      records.filter((record) => {
        if (mode !== "all" && record.mode !== mode) return false;
        if (positionId !== "all" && record.positionId !== positionId) return false;
        return true;
      }),
    [mode, positionId, records],
  );

  return (
    <section className="page page-records">
      <header className="page-hero">
        <div className="page-hero-copy">
          <span className="page-eyebrow">记录复盘</span>
          <h1>先筛选和浏览，再进入单条详情复盘</h1>
          <p>列表只显示模式、岗位、日期和题数，完整 transcript、提词卡和表达指标都放进详情页。</p>
        </div>
        <button className="button primary" type="button" onClick={onMock}>
          去做第一次模拟
        </button>
      </header>

      <section className="surface-card">
        <div className="surface-card-inner">
          <div className="filter-bar">
            <div className="filter-label">
              <Filter size={16} />
              <span>筛选</span>
            </div>
            <div className="filter-controls">
              <select className="input" aria-label="按模式筛选" value={mode} onChange={(event) => setMode(event.target.value as RecordsFilterMode)}>
                <option value="all">全部模式</option>
                <option value="live">实时助手</option>
                <option value="mock">模拟面试</option>
              </select>
              <select className="input" aria-label="按岗位筛选" value={positionId} onChange={(event) => setPositionId(event.target.value)}>
                <option value="all">全部岗位</option>
                {positions.map((position) => (
                  <option key={position.id} value={position.id}>
                    {repairText(position.company)} · {repairText(position.title)}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {filtered.length === 0 ? (
            <div className="records-empty-shell">
              <EmptyState title="还没有复盘记录" detail="完成一次模拟面试或结束一次实时助手后，这里会出现可筛选的记录。" />
              <button className="button primary" type="button" onClick={onMock}>
                去做第一次模拟
              </button>
            </div>
          ) : (
            <div className="records-list">
              {filtered.map((record) => {
                const position = positions.find((item) => item.id === record.positionId);
                return (
                  <button key={record.id} type="button" className="records-list-item" onClick={() => onOpen(record.id)}>
                    <div className="records-list-main">
                      <div className="records-list-top">
                        <span className={record.mode === "live" ? "status-chip" : "status-chip positive"}>{record.mode === "live" ? "实时" : "模拟"}</span>
                        <span>{formatRecordTime(record.createdAt)}</span>
                      </div>
                      <strong>{position ? `${repairText(position.company)} · ${repairText(position.title)}` : repairText(record.title)}</strong>
                      <p>{repairText(record.summary)}</p>
                    </div>
                    <div className="records-list-side">
                      <small>{record.transcript.filter((item) => item.role === "interviewer").length} 题</small>
                      <ChevronRight size={18} />
                    </div>
                  </button>
                );
              })}
            </div>
          )}
        </div>
      </section>
    </section>
  );
}

export function RecordReportView({
