@import "@fontsource/noto-sans-sc/700.css";

:root {
  --bg: var(--color-bg);
  --surface: var(--color-surface);
  --surface-muted: var(--color-surface-muted);
  --ink: var(--color-ink);
  --muted: var(--color-muted);
  --line: var(--color-line);
  --accent: var(--color-accent);
  --accent-strong: var(--color-accent-strong);
  --accent-soft: var(--color-accent-soft);
  --shadow: var(--shadow-md);
  --radius: var(--radius);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100dvh;
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: var(--leading-relaxed);
  color: var(--color-ink);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background:
    linear-gradient(180deg, rgb(255 255 255 / 0.72), transparent 380px),
    var(--bg);
}

p {
  margin: 0 0 0.5em;
  line-height: var(--leading-normal);
}

button,
textarea,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.56;
}

.app-shell {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  min-height: 100dvh;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: 12px;
  z-index: 40;
  padding: 8px 12px;
  border-radius: 8px;
  color: #fff;
  background: var(--ink);
  transform: translateY(-140%);
  transition: transform 160ms ease;
}

.skip-link:focus {
  transform: translateY(0);
}

.app-shell-v2 {
  grid-template-columns: 80px minmax(0, 1fr);
  background:
    radial-gradient(circle at top left, rgb(239 244 245 / 0.78), transparent 320px),
    linear-gradient(180deg, rgb(255 255 255 / 0.8), transparent 380px),
    var(--bg);
}

.icon-sidebar {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  height: 100dvh;
  padding: 18px 12px;
  border-right: 1px solid var(--line);
  background: rgb(255 255 255 / 0.88);
  backdrop-filter: blur(18px);
}

.icon-brand,
.icon-account-entry,
.icon-nav-item {
  width: 48px;
  height: 48px;
  border: 1px solid transparent;
  border-radius: 14px;
  color: var(--muted);
  background: transparent;
}

.icon-brand {
  display: grid;
  place-items: center;
  margin-bottom: 6px;
}

.icon-brand-mark {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  color: #215d8f;
  background: #e8f0f9;
}

.icon-nav-list {
  display: grid;
  gap: 10px;
}

.icon-nav-item {
  display: grid;
  place-items: center;
}

.icon-nav-item:hover,
.icon-account-entry:hover,
.icon-brand:hover,
.icon-nav-item:focus-visible,
.icon-account-entry:focus-visible,
.icon-brand:focus-visible {
  color: var(--ink);
  background: #f2f5f8;
  outline: none;
}

.icon-nav-item.active {
  color: #215d8f;
  border-color: #c8d8ea;
  background: #edf4fb;
  box-shadow: inset 3px 0 0 #3d78b2;
}

.icon-account-entry {
  margin-top: auto;
  display: grid;
  place-items: center;
  color: var(--ink);
  background: #f7f7f5;
  border-color: var(--line);
}

.main-v2 {
  width: min(100%, 1280px);
  padding: 32px 32px 40px;
}

.page-kicker {
  margin: 0 0 8px;
  color: var(--color-text-subtle);
  font-size: 12px;
  line-height: 1.6;
}

.home-workbench {
  display: grid;
  gap: 24px;
}

.home-workbench-header,
.home-launch-panel,
.position-card,
.position-empty-state,
.home-drawer,
.home-drawer-note {
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgb(255 255 255 / 0.94);
  box-shadow: var(--shadow-md);
}

.home-workbench-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  padding: 24px;
}

.home-workbench-header h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 500;
  line-height: 1.2;
}

.home-workbench-header p {
  margin: 8px 0 0;
  max-width: 560px;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.6;
}

.position-stack {
  display: grid;
  gap: 16px;
}

.position-card {
  position: relative;
  display: grid;
  grid-template-columns: 6px minmax(0, 1fr);
  width: 100%;
  padding: 0;
  color: inherit;
  text-align: left;
  overflow: hidden;
}

.position-card-rail {
  background: transparent;
  transition: background-color 160ms ease;
}

.position-card-main {
  display: grid;
  gap: 16px;
  padding: 20px 24px;
}

.position-card.active .position-card-rail {
  background: #3d78b2;
}

.position-card.active {
  background: #f5f9fd;
  border-color: #c9d9ea;
}

.position-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.position-label {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  min-height: 24px;
  padding: 0 10px;
  border-radius: 999px;
  color: var(--color-text-subtle);
  background: #f4f6f8;
  font-size: 12px;
  line-height: 1.6;
}

.position-card h2,
.position-empty-state h2,
.home-drawer h2 {
  margin: 8px 0 0;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.6;
}

.position-card p,
.position-empty-state p,
.home-launch-main p,
.home-drawer-note p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.6;
}

.position-score {
  font-size: 16px;
  font-weight: 500;
  color: #215d8f;
  font-variant-numeric: tabular-nums;
}

.position-pill-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.position-pill {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 12px;
  border-radius: 999px;
  color: #35536d;
  background: #eff4f8;
  font-size: 12px;
  line-height: 1.6;
}

.position-empty-state {
  display: grid;
  justify-items: start;
  gap: 16px;
  padding: 32px;
}

.position-empty-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 14px;
  color: #215d8f;
  background: #e8f0f9;
}

.home-launch-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 24px;
  padding: 24px;
}

.home-launch-main {
  display: grid;
  gap: 8px;
}

.home-launch-main strong {
  font-size: 16px;
  font-weight: 500;
  line-height: 1.6;
}

.home-launch-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 12px;
}

.home-primary-action {
  min-width: 200px;
}

.drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 25;
  background: rgb(18 26 33 / 0.26);
}

.home-drawer {
  position: absolute;
  top: 0;
  right: 0;
  display: grid;
  gap: 24px;
  width: min(420px, 100vw);
  height: 100dvh;
  padding: 24px;
  border-radius: 0;
  border-top: 0;
  border-right: 0;
  border-bottom: 0;
  box-shadow: -24px 0 64px rgb(18 26 33 / 0.16);
}

.home-drawer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.home-drawer-form {
  display: grid;
  gap: 16px;
}

.home-drawer-form textarea {
  width: 100%;
  min-height: 320px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 12px;
  resize: vertical;
  font-size: 14px;
  line-height: 1.6;
}

.home-drawer-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

.home-drawer-note {
  display: grid;
  gap: 8px;
  padding: 16px;
  background: #f7f9fb;
}

.sidebar {
  position: sticky;
  top: 0;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 22px 16px;
  border-right: 1px solid var(--line);
  background: rgb(255 255 255 / 0.78);
  backdrop-filter: blur(18px);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 8px 14px;
  border-bottom: 1px solid var(--line);
}

.brand-button {
  width: 100%;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
}

.brand-mark,
.header-icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  border-radius: var(--radius);
  color: var(--accent-strong);
  background: var(--accent-soft);
}

.brand strong,
.brand span {
  display: block;
}

.brand strong {
  font-size: 15px;
}

.brand span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
}

.nav-list {
  display: grid;
  gap: 4px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 40px;
  padding: 9px 11px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--muted);
  background: transparent;
  text-align: left;
}

.nav-item:hover,
.nav-item:focus-visible {
  color: var(--ink);
  background: var(--surface-muted);
  outline: none;
}

.nav-item.active {
  color: var(--accent-strong);
  border-color: #c7dccd;
  background: var(--accent-soft);
}

.compliance-note {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--muted);
  background: var(--color-surface-muted);
}

.compliance-note p {
  margin: 0;
  font-size: 12px;
  line-height: 1.5;
}

.account-entry {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--ink);
  background: var(--color-surface-muted);
  text-align: left;
}

.account-entry span,
.account-entry small {
  display: block;
}

.account-entry small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
}

.main {
  width: min(100%, 1200px);
  margin: 0 auto;
  padding: var(--space-2xl) var(--space-xl);
}

.topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.76);
  box-shadow: var(--shadow);
}

.topbar h1 {
  max-width: 780px;
  margin: 3px 0 0;
  font-size: clamp(28px, 4vw, 44px);
  line-height: 1.2;
  font-family: var(--font-heading);
  font-weight: 700;
  color: var(--color-ink);
}

.focus-topbar h1 {
  max-width: 880px;
}

.eyebrow {
  margin: 0;
  color: var(--accent);
  font-size: 13px;
  font-weight: 700;
}

.topbar-actions,
.section-action,
.mock-actions,
.sticky-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 38px;
  padding: 9px 14px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  font-weight: 700;
  text-decoration: none;
  transition:
    transform 150ms ease,
    border-color 150ms ease,
    background-color 150ms ease;
}

.button:active {
  transform: translateY(1px);
}

.button.primary {
  color: #fff;
  background: var(--accent-strong);
}

.button.primary:hover,
.button.primary:focus-visible {
  background: var(--color-accent-strong);
  outline: 3px solid rgb(37 108 74 / 0.22);
}

.button.secondary {
  color: var(--ink);
  border-color: var(--line);
  background: #fff;
}

.button.secondary:hover,
.button.secondary:focus-visible {
  border-color: #b6c8bb;
  background: var(--color-surface-hover);
  outline: none;
}

.button.text-button {
  min-height: 32px;
  padding: 4px 0;
  color: var(--accent);
  background: transparent;
}

.button.danger {
  color: #fff;
  background: var(--danger);
}

.file-button input {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  opacity: 0;
  pointer-events: none;
}

.page-section {
  display: grid;
  gap: var(--space-2xl);
}

.today-workbench {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: var(--space-xl);
  align-items: stretch;
  padding: var(--space-xl);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.workbench-copy {
  display: grid;
  align-content: center;
  gap: 12px;
}

.quiet-label {
  color: var(--accent);
  font-size: 13px;
  font-weight: 800;
}

.workbench-copy h2 {
  margin: 0;
  font-size: clamp(26px, 3vw, 38px);
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  text-wrap: balance;
}

.workbench-copy p,
.progress-card p,
.next-action-strip p,
.status-tile p,
.priority-item small {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.workbench-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 6px;
}

.progress-card {
  display: grid;
  align-content: center;
  gap: 10px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--color-surface-muted);
}

.progress-card span,
.status-tile span,
.score-panel span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
}

.progress-card strong {
  font-size: 42px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.progress-card meter {
  width: 100%;
}

.status-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.status-tile {
  display: grid;
  gap: 8px;
  min-height: 132px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: inherit;
  background: var(--surface);
  text-align: left;
  box-shadow: var(--shadow);
}

.status-tile:hover,
.status-tile:focus-visible,
.priority-item:hover,
.priority-item:focus-visible,
.training-row:hover,
.training-row:focus-visible {
  border-color: var(--color-line);
  background: #f7fbf8;
  outline: none;
}

.status-tile strong {
  font-size: 28px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.next-action-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.76);
}

.next-action-strip strong {
  display: block;
  margin-bottom: 4px;
}

.metrics-grid,
.plan-grid,
.business-panel,
.privacy-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.metric-card,
.panel,
.question-card,
.plan-card,
.privacy-item,
.workflow-step,
.report-hero,
.boundary-item,
.priority-item {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.metric-card {
  display: grid;
  gap: 8px;
  padding: 16px;
}

.metric-card > svg {
  color: var(--accent);
}

.metric-card span,
.metric-card p,
.metric-card small {
  color: var(--muted);
}

.metric-card span {
  font-size: 13px;
  font-weight: 700;
}

.metric-card strong {
  font-size: 34px;
  line-height: 1;
}

.metric-card p {
  min-height: 38px;
  margin: 0;
  font-size: 13px;
  line-height: 1.45;
}

.workflow {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.workflow-step {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 8px;
  min-height: 110px;
  padding: 14px;
  text-align: left;
}

.workflow-step > span {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  color: #fff;
  background: var(--accent);
  font-size: 13px;
  font-weight: 800;
}

.workflow-step small {
  grid-column: 2 / 3;
  color: var(--muted);
  line-height: 1.5;
}

.workflow-step:hover,
.workflow-step:focus-visible {
  border-color: #b3cbbb;
  outline: none;
  transform: translateY(-1px);
}

.split-grid,
.editor-grid,
.mock-layout,
.answer-layout,
.diagnosis-grid,
.training-grid,
.boundary-grid,
.priority-strip {
  display: grid;
  gap: 16px;
}

.split-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.editor-grid {
  grid-template-columns: minmax(0, 1.1fr) minmax(360px, 0.9fr);
  align-items: start;
}

.mock-layout {
  grid-template-columns: 340px minmax(0, 1fr);
  align-items: start;
}

.answer-layout {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.diagnosis-grid {
  grid-template-columns: minmax(240px, 0.95fr) minmax(0, 1.2fr) repeat(2, minmax(210px, 0.7fr));
}

.score-panel {
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.score-panel strong {
  display: inline-block;
  margin: 8px 4px 8px 0;
  font-size: 44px;
  line-height: 0.95;
  font-variant-numeric: tabular-nums;
}

.score-panel small {
  color: var(--muted);
  font-weight: 800;
}

.score-panel p {
  max-width: 62ch;
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.target-summary {
  display: grid;
  gap: 8px;
}

.target-summary strong {
  font-size: 18px;
}

.target-summary span {
  width: fit-content;
  padding: 5px 9px;
  border-radius: 999px;
  color: var(--accent-strong);
  background: var(--accent-soft);
  font-size: 13px;
  font-weight: 800;
}

.target-summary p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.priority-strip {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.priority-item {
  display: grid;
  gap: 9px;
  min-height: 158px;
  padding: 16px;
  color: inherit;
  text-align: left;
}

.priority-item > span,
.training-row span {
  width: fit-content;
  padding: 3px 8px;
  border-radius: 999px;
  color: var(--accent-strong);
  background: var(--accent-soft);
  font-size: 12px;
  font-weight: 800;
}

.priority-item strong {
  line-height: 1.42;
}

.training-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.training-list {
  display: grid;
  gap: 8px;
}

.training-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: start;
  width: 100%;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--ink);
  background: var(--color-surface-muted);
  text-align: left;
}

.training-row strong {
  font-size: 14px;
  line-height: 1.5;
}

.boundary-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.boundary-item {
  display: grid;
  gap: 9px;
  padding: 16px;
}

.boundary-item svg {
  color: var(--accent);
}

.boundary-item.warning svg {
  color: var(--warning);
}

.boundary-item p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.section-header {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.76);
}

.section-header h2,
.panel h2 {
  margin: 0;
  font-size: 20px;
}

.section-header p {
  margin: 4px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.panel {
  min-width: 0;
  padding: 16px;
}

.panel > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.gap-list,
.evidence-list,
.rewrite-list,
.action-list,
.dimension-list,
.insight-stack,
.question-rail,
.danger-zone {
  display: grid;
  gap: 10px;
}

.gap-item,
.evidence-item,
.rewrite-list article,
.rail-item,
.turn-feedback {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--color-surface-muted);
}

.gap-item span,
.evidence-item span,
.question-meta span,
.large-question span,
.rail-item span {
  display: inline-flex;
  width: fit-content;
  margin-bottom: 6px;
  padding: 3px 8px;
  border-radius: 999px;
  color: var(--accent-strong);
  background: var(--accent-soft);
  font-size: 12px;
  font-weight: 800;
}

.gap-item.gap span {
  color: #7a4b00;
  background: #fbefd7;
}

.gap-item.risk span {
  color: #8b251f;
  background: #fbe3e1;
}

.gap-item strong,
.evidence-item strong {
  display: block;
}

.gap-item p,
.evidence-item p,
.rewrite-list p,
.evidence-item small,
.action-list,
.number-list,
.risk-copy,
.answer-text,
.question-card p,
.plan-card p,
.privacy-item p {
  color: var(--muted);
  line-height: 1.58;
}

.action-list,
.number-list,
.plan-card ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.action-list li,
.plan-card li {
  display: flex;
  gap: 9px;
  align-items: flex-start;
}

.action-list svg,
.plan-card svg {
  flex: 0 0 auto;
  margin-top: 2px;
  color: var(--accent);
}

.text-editor,
.mock-room textarea {
  width: 100%;
  min-height: 620px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--ink);
  background: #fff;
  line-height: 1.64;
  resize: vertical;
}

.text-editor:focus,
.mock-room textarea:focus {
  border-color: var(--accent);
  outline: 3px solid rgb(37 108 74 / 0.16);
}

.sticky-actions {
  position: sticky;
  bottom: 12px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.88);
  backdrop-filter: blur(12px);
}

.rewrite-list article {
  display: grid;
  gap: 8px;
}

.rewrite-list .before {
  margin: 0;
  color: #7a4b00;
}

.rewrite-list .after {
  margin: 0;
  color: var(--ink);
  font-weight: 700;
}

.tag-block + .tag-block {
  margin-top: 16px;
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 9px;
}

.tags span {
  padding: 6px 9px;
  border: 1px solid #c7dccd;
  border-radius: 999px;
  color: var(--accent-strong);
  background: var(--color-accent-green-bg);
  font-size: 13px;
  font-weight: 700;
}

.number-list {
  counter-reset: number;
  display: grid;
  gap: 10px;
}

.number-list li {
  counter-increment: number;
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 8px;
  color: var(--muted);
  line-height: 1.55;
}

.number-list li::before {
  content: counter(number);
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  color: var(--accent);
  background: var(--accent-soft);
  font-size: 12px;
  font-weight: 800;
}

.segmented {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.74);
}

.segmented button {
  min-height: 34px;
  padding: 7px 12px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--muted);
  background: transparent;
  font-weight: 700;
}

.segmented button.active,
.segmented button:hover,
.segmented button:focus-visible {
  color: var(--accent-strong);
  border-color: #c7dccd;
  background: var(--accent-soft);
  outline: none;
}

.question-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.question-card {
  display: grid;
  gap: 12px;
  padding: 16px;
}

.question-card h3 {
  margin: 0;
  font-size: 17px;
  line-height: 1.45;
}

.question-card p {
  margin: 0;
}

.question-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.large-question h2 {
  margin: 0;
  font-size: 28px;
  line-height: 1.24;
}

.large-question p {
  color: var(--muted);
}

.answer-text,
.risk-copy {
  margin: 0;
}

.evidence-list.compact .evidence-item p {
  margin-bottom: 0;
}

.question-rail {
  max-height: calc(100dvh - 180px);
  overflow: auto;
}

.rail-item {
  display: grid;
  gap: 4px;
  width: 100%;
  color: var(--ink);
  text-align: left;
}

.rail-item strong {
  font-size: 14px;
  line-height: 1.46;
}

.rail-item.active {
  border-color: #9fc2aa;
  background: var(--accent-soft);
}

.mock-room {
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.mock-room h2 {
  margin: 0;
  font-size: 26px;
  line-height: 1.28;
}

.mock-room textarea {
  min-height: 330px;
}

.timer-strip {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: var(--radius);
  color: var(--accent-strong);
  background: var(--accent-soft);
  font-size: 13px;
  font-weight: 800;
}

.turn-feedback {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  border-color: #b7d0bd;
  background: var(--color-accent-green-bg);
}

.turn-feedback strong {
  font-size: 28px;
  color: var(--accent-strong);
}

.turn-feedback p {
  margin: 0;
  color: var(--muted);
}

.feedback-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.form-hint,
.inline-message {
  margin: -4px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.form-hint.warning,
.inline-message.error {
  color: var(--danger);
}

.inline-message {
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--color-surface-muted);
}

.inline-message.success {
  color: var(--accent-strong);
  border-color: #b7d0bd;
  background: var(--color-accent-green-bg);
}

.inline-message.error {
  border-color: #efc2bd;
  background: #fff7f6;
}

.empty-state {
  padding: 18px;
  border: 1px dashed #b9c7bd;
  border-radius: var(--radius);
  background: var(--color-surface-muted);
}

.empty-state p {
  margin: 6px 0 0;
  color: var(--muted);
  line-height: 1.55;
}

.report-hero {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 18px;
  padding: 20px;
}

.report-hero div {
  min-width: 180px;
}

.report-hero span,
.report-hero small {
  color: var(--muted);
  font-weight: 700;
}

.report-hero strong {
  display: inline-block;
  margin: 0 4px;
  font-size: 44px;
  line-height: 1;
}

.report-hero p {
  margin: 0;
  color: var(--muted);
  font-size: 18px;
  line-height: 1.55;
}

.dimension-row {
  display: grid;
  grid-template-columns: 92px 1fr 40px;
  gap: 10px;
  align-items: center;
}

.dimension-row meter {
  width: 100%;
  height: 12px;
}

.dimension-row strong {
  text-align: right;
}

.plan-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.plan-card {
  position: relative;
  display: grid;
  gap: 12px;
  padding: 18px;
}

.plan-card.recommended {
  border-color: #93bd9f;
  background: #f7fbf8;
}

.plan-card h3,
.plan-card p {
  margin: 0;
}

.plan-card > strong {
  font-size: 30px;
}

.plan-card ul {
  display: grid;
  gap: 8px;
}

.recommend-badge {
  width: fit-content;
  padding: 4px 8px;
  border-radius: 999px;
  color: #fff;
  background: var(--accent);
  font-size: 12px;
  font-weight: 800;
}

.business-panel {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.privacy-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.privacy-item {
  display: grid;
  gap: 8px;
  padding: 16px;
}

.privacy-item svg {
  color: var(--accent);
}

.privacy-item p {
  margin: 0;
}

@media (max-width: 1180px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: static;
    height: auto;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .nav-list {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .compliance-note {
    margin-top: 0;
  }

  .workflow,
  .metrics-grid,
  .plan-grid,
  .privacy-grid,
  .diagnosis-grid,
  .boundary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .question-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .editor-grid,
  .mock-layout {
    grid-template-columns: 1fr;
  }

  .today-workbench {
    grid-template-columns: 1fr;
  }

  .question-rail {
    max-height: none;
  }
}

@media (max-width: 760px) {
  .main {
    padding: 12px 14px 14px;
  }

  .sidebar {
    position: sticky;
    z-index: 5;
    top: 0;
    width: 100%;
    gap: 8px;
    padding: 10px 12px;
    background: rgb(255 255 255 / 0.92);
  }

  .brand {
    padding: 0 2px 8px;
  }

  .nav-list {
    display: flex;
    gap: 6px;
    overflow-x: auto;
    padding-bottom: 2px;
    scrollbar-width: none;
  }

  .nav-item {
    flex: 0 0 auto;
    width: auto;
    min-height: 38px;
    padding: 8px 10px;
    font-size: 13px;
    white-space: nowrap;
  }

  .nav-list::-webkit-scrollbar,
  .nav-item svg,
  .compliance-note {
    display: none;
  }

  .topbar {
    padding: 14px;
    margin-bottom: 14px;
  }

  .topbar,
  .section-header,
  .report-hero {
    grid-template-columns: 1fr;
  }

  .topbar {
    flex-direction: column;
  }

  .topbar h1 {
    font-size: 24px;
    line-height: 1.18;
  }

  .topbar-actions,
  .section-action,
  .workbench-actions,
  .feedback-actions {
    width: 100%;
    justify-content: stretch;
  }

  .button {
    width: 100%;
  }

  .workflow,
  .metrics-grid,
  .status-row,
  .split-grid,
  .answer-layout,
  .question-grid,
  .plan-grid,
  .business-panel,
  .privacy-grid,
  .diagnosis-grid,
  .priority-strip,
  .training-grid,
  .boundary-grid {
    grid-template-columns: 1fr;
  }

  .today-workbench {
    padding: 16px;
  }

  .workbench-copy h2 {
    font-size: 25px;
  }

  .progress-card strong,
  .score-panel strong {
    font-size: 42px;
  }

  .next-action-strip {
    display: grid;
  }

  .text-editor {
    min-height: 420px;
  }

  .turn-feedback {
    grid-template-columns: 1fr;
  }

  .dimension-row {
    grid-template-columns: 78px 1fr 36px;
  }
}

.ai-toggle {
  font-variant-numeric: tabular-nums;
}

.ai-banner {
  margin: -8px 0 16px;
}

.voice-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.voice-actions .form-hint {
  margin: 0;
}

.nav-group {
  display: grid;
  gap: 4px;
  padding-bottom: 10px;
  margin-bottom: 6px;
  border-bottom: 1px solid var(--line);
}

.nav-group:last-child {
  border-bottom: 0;
  margin-bottom: 0;
  padding-bottom: 0;
}

.board-columns {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
  align-items: start;
}

.board-column {
  display: grid;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.7);
}

.board-column > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 800;
  color: var(--muted);
}

.board-column > header span {
  display: grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 999px;
  color: var(--accent-strong);
  background: var(--accent-soft);
  font-size: 12px;
}

.board-cards {
  display: grid;
  gap: 10px;
}

.board-card {
  display: grid;
  gap: 5px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.board-card.active {
  border-color: #9fc2aa;
  background: var(--accent-soft);
}

.board-card > strong {
  font-size: 15px;
