}

.board-add textarea {
  width: 100%;
  min-height: 160px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
  line-height: 1.6;
  resize: vertical;
}

.board-add textarea:focus {
  border-color: var(--accent);
  outline: 3px solid rgb(37 108 74 / 0.16);
}

.account-actions {
