}

.match-pill {
  flex: 0 0 auto;
  padding: 3px 9px;
  border-radius: 999px;
  color: var(--accent-strong);
  background: var(--accent-soft);
  font-size: 12px;
  font-weight: 800;
}

.recommend-card p {
