}

.highlight-list li {
  display: flex;
  gap: 9px;
  align-items: flex-start;
  color: var(--ink);
  line-height: 1.55;
}

.highlight-list svg {
  flex: 0 0 auto;
  margin-top: 3px;
  color: var(--accent);
