  flex-wrap: wrap;
  gap: 8px;
}

.evidence-edit {
  gap: 8px;
}

.evidence-edit textarea {
  width: 100%;
  min-height: 90px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--ink);
  background: #fff;
  resize: vertical;
  line-height: 1.55;
}

.transcript-list {
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
