  gap: 14px;
}

.dimension-item {
  display: grid;
  gap: 8px;
}

.dimension-item header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.dimension-item header span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}

.score-track {
