  white-space: nowrap;
  border: 0;
}

.hero-task-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.75fr);
  gap: 18px;
  align-items: start;
}

.hero-jd-panel,
.jd-editor-panel,
.mock-stage,
.transcript-panel,
.account-modal {
