  grid-template-columns: 220px minmax(0, 1fr) 360px;
  gap: 16px;
  align-items: start;
}

.resume-workspace.compact {
  grid-template-columns: 180px minmax(0, 1fr) 320px;
}

.resume-section-nav,
.resume-ai-panel {
  position: sticky;
  top: 24px;
  display: grid;
  gap: 10px;
  padding: 16px;
}

.resume-section-nav header,
.resume-ai-panel header {
  display: grid;
  gap: 4px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.resume-section-tab {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 38px;
  padding: 9px 10px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--muted);
  background: transparent;
  text-align: left;
}

.resume-section-tab.active,
.resume-section-tab:hover {
  color: var(--ink);
  border-color: var(--line);
  background: var(--surface-muted);
}

.resume-document {
  display: grid;
  gap: 14px;
}

.resume-profile-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px;
}

.resume-avatar {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  color: #fff;
  background: var(--ink);
  font-size: 28px;
  font-weight: 900;
}

.resume-edit-card {
  display: grid;
  gap: 12px;
  padding: 18px;
}

.resume-card-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.resume-edit-card textarea {
  width: 100%;
  min-height: 260px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  resize: vertical;
  line-height: 1.68;
}

.resume-parsed-grid {
  display: grid;
  gap: 12px;
}

.parsed-card {
  display: grid;
  gap: 7px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  cursor: pointer;
}

.parsed-card.active {
  border-color: var(--ink);
}

.resume-ai-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.resume-ai-actions button {
  min-height: 32px;
  padding: 6px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-muted);
}

.resume-chat-thread {
  display: grid;
  gap: 10px;
  max-height: calc(100dvh - 250px);
  overflow: auto;
}

.resume-chat-message {
  padding: 11px 12px;
  border-radius: 16px;
  background: var(--surface-muted);
}

.resume-chat-message.user {
  background: var(--color-line);
}

.resume-chat-message p {
  margin: 0;
  line-height: 1.55;
}

.suggestion-box {
  display: grid;
  gap: 8px;
  margin-top: 10px;
}

.suggestion-box pre {
  white-space: pre-wrap;
  margin: 0;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
  font-family: inherit;
  line-height: 1.55;
}

.resume-chat-input {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}

/* Mock progress bar */
.mock-progress-bar {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-md) var(--space-lg);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.mock-progress-stat {
  display: grid;
  gap: 2px;
  color: var(--muted);
  font-size: var(--text-sm);
  font-weight: 800;
}

.mock-progress-stat strong {
  font-size: var(--text-xl);
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.mock-progress-rail {
  display: flex;
  flex: 1;
  gap: 4px;
  align-items: center;
}

.mock-progress-dot {
  flex: 1;
  height: 8px;
  border: 0;
  border-radius: 999px;
  background: var(--surface-muted);
  padding: 0;
  transition: background 0.2s;
}

.mock-progress-dot.filled {
  background: var(--color-success);
}

.mock-progress-dot.current {
  background: var(--color-accent);
}

/* Persona selector */
.persona-selector {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
}

.persona-card {
  flex: 1;
  min-width: 140px;
  padding: var(--space-lg);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  text-align: left;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.persona-card:hover {
  border-color: var(--color-text-secondary);
}

.persona-card.active {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 1px var(--color-accent);
}

.persona-card strong {
  display: block;
  margin-bottom: 4px;
  font-size: var(--text-base);
}

.persona-card small {
  color: var(--muted);
  font-size: var(--text-sm);
  line-height: var(--leading-normal);
}

/* Interactive cue card */
.cue-bullets-checkable {
  list-style: none;
  margin: 0;
  padding: 0;
}

.cue-bullet {
  display: flex;
  align-items: baseline;
  gap: var(--space-sm);
  padding: 10px 0;
  border-top: 1px solid var(--line);
  line-height: var(--leading-normal);
  cursor: pointer;
  user-select: none;
}

.cue-bullet:first-child {
  border-top: none;
}

.cue-bullet::before {
  content: "";
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  margin-top: 3px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  transition: background 0.15s, border-color 0.15s;
}

.cue-bullet.checked {
  color: var(--color-text-secondary);
}

.cue-bullet.checked::before {
  background: var(--color-accent);
  border-color: var(--color-accent);
}

@media (max-width: 1180px) {
  .guided-hero,
  .onboarding-layout,
  .room-grid,
  .resume-workspace {
    grid-template-columns: 1fr;
  }

  .prep-side-panel,
  .resume-section-nav,
  .resume-ai-panel {
    position: static;
  }

  .resume-section-nav {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .resume-section-nav header {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1180px) {
  .guided-hero,
  .onboarding-layout,
  .room-grid,
  .resume-workspace {
    grid-template-columns: 1fr;
  }

  .prep-side-panel,
  .resume-section-nav,
  .resume-ai-panel {
