  }

  .resume-section-nav {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .resume-section-nav header {
    grid-column: 1 / -1;
  }
}

@media (max-width: 760px) {
  .guided-hero h1 {
    font-size: 28px;
  }

  .job-card-body,
  .config-option-grid,
  .config-choice-grid,
  .chat-composer,
  .assistant-actions,
  .resume-chat-input {
    grid-template-columns: 1fr;
  }

  .chat-bubble,
  .room-message {
