  }

  .voice-dock {
    flex-wrap: wrap;
  }

  .voice-dock .button,
  .generated-job-card footer .button,
  .resume-card-actions .button {
    width: 100%;
  }

  .resume-section-nav {
    grid-template-columns: 1fr;
  }
}

