@import "@fontsource/noto-serif-sc/400.css";
@import "@fontsource/noto-serif-sc/700.css";
@import "@fontsource/noto-sans-sc/400.css";
@import "@fontsource/noto-sans-sc/500.css";
@import "@fontsource/noto-sans-sc/600.css";
@import "@fontsource/noto-sans-sc/700.css";

:root {
  --bg: var(--color-bg);
  --surface: var(--color-surface);
  --surface-muted: #fafaf8;
  --ink: var(--color-ink);
  --muted: var(--color-text-secondary);
  --subtle: var(--color-text-subtle);
  --line: #d8ddd8;
  --line-strong: #c9d1cc;
  --accent: #215d8f;
  --accent-strong: #1b4d77;
  --accent-soft: #edf4fb;
  --success-soft: #eef8f1;
  --success-ink: #256d3e;
  --warn-soft: #fcf2df;
  --warn-ink: #8a5a16;
  --danger: #b42318;
  --shadow-soft: 0 14px 30px rgb(20 39 59 / 0.05);
  --shadow-float: 0 16px 36px rgb(20 39 59 / 0.06);
  --radius-card: 18px;
  --radius-control: 14px;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100dvh;
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.6;
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background:
    linear-gradient(180deg, rgb(255 255 255 / 0.88), transparent 320px),
    var(--bg);
}

p,
h1,
h2,
h3 {
  margin: 0;
}

button,
textarea,
input,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.56;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: 12px;
  z-index: 40;
  padding: 8px 12px;
  border-radius: 8px;
  color: #fff;
  background: var(--ink);
  transform: translateY(-140%);
  transition: transform 160ms ease;
}

.skip-link:focus {
  transform: translateY(0);
}

.app-shell-v3 {
  display: grid;
  grid-template-columns: 84px minmax(0, 1fr);
  min-height: 100dvh;
}

.app-shell-v3.expanded {
  grid-template-columns: 216px minmax(0, 1fr);
}

.shell-sidebar {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  gap: 18px;
  height: 100dvh;
  padding: 18px 12px;
  border-right: 1px solid var(--line);
  background: rgb(255 255 255 / 0.9);
  backdrop-filter: blur(18px);
}

.shell-sidebar.expanded {
  padding-inline: 14px;
}

.shell-brand {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.shell-brand-button,
.shell-account,
.shell-nav-item,
.mobile-topbar-button,
.quiet-toggle {
  border: 0;
  background: transparent;
}

.shell-brand-button {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 6px 4px;
  color: inherit;
  text-align: left;
}

.shell-brand-mark,
.shell-nav-icon,
.mobile-topbar-button,
.empty-card-icon,
.resume-avatar {
  display: grid;
  place-items: center;
}

.shell-brand-mark,
.empty-card-icon {
  width: 42px;
  height: 42px;
  border-radius: 14px;
  color: var(--accent);
  background: var(--accent-soft);
}

.shell-brand-copy,
.shell-account-copy,
.mobile-topbar-copy,
.desktop-page-title {
  display: grid;
  min-width: 0;
}

.shell-brand-copy strong,
.mobile-topbar-copy strong {
  font-size: 15px;
  font-weight: 600;
}

.shell-brand-copy small,
.shell-account-copy small,
.mobile-topbar-copy small {
  color: var(--subtle);
  font-size: 12px;
  line-height: 1.5;
}

.shell-collapse-button {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--muted);
  background: #fff;
}

.shell-nav {
  display: grid;
  gap: 10px;
}

.shell-nav-item,
.shell-account {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: var(--radius-control);
  color: var(--muted);
  text-align: left;
}

.shell-nav-item:hover,
.shell-nav-item:focus-visible,
.shell-account:hover,
.shell-account:focus-visible,
.shell-brand-button:hover,
.shell-brand-button:focus-visible,
.mobile-topbar-button:hover,
.mobile-topbar-button:focus-visible,
.quiet-toggle:hover,
.quiet-toggle:focus-visible {
  outline: none;
  color: var(--ink);
  background: #f5f7f8;
}

.shell-nav-item.active {
  color: var(--accent);
  border-color: #c7d7e9;
  background: var(--accent-soft);
}

.shell-nav-icon,
.mobile-topbar-button {
  width: 32px;
  height: 32px;
  border-radius: 12px;
  color: currentcolor;
}

.shell-account {
  margin-top: auto;
  color: var(--ink);
  background: #f7f8f6;
  border-color: var(--line);
}

.main-v3 {
  width: min(100%, 1320px);
  margin: 0 auto;
  padding: 32px;
}

.mobile-topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
  background: rgb(255 255 255 / 0.9);
  backdrop-filter: blur(18px);
}

.mobile-drawer-backdrop,
.drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  background: rgb(17 24 39 / 0.24);
}

.mobile-drawer,
.drawer-panel,
.dialog-panel {
  display: grid;
  align-content: start;
  gap: 20px;
  padding: 24px;
  background: rgb(252 253 254 / 0.98);
  box-shadow: -24px 0 56px rgb(17 24 39 / 0.16);
}

.mobile-drawer {
  justify-self: start;
  width: min(320px, 92vw);
  height: 100dvh;
}

.drawer-panel {
  justify-self: end;
  width: min(460px, 100vw);
  height: 100dvh;
}

.drawer-panel.narrow {
  width: min(420px, 100vw);
}

.dialog-panel {
  justify-self: center;
  align-self: center;
  width: min(420px, calc(100vw - 32px));
  border-radius: 24px;
  box-shadow: 0 22px 58px rgb(17 24 39 / 0.18);
}

.compact-dialog {
  width: min(380px, calc(100vw - 32px));
}

.drawer-header,
.section-row-header,
.desktop-page-header,
.desktop-topbar,
.position-summary-head,
.position-summary-score,
.filter-bar,
.records-list-top,
.records-list-item,
.summary-strip,
.resume-profile-head,
.question-bank-row-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.page,
.desktop-page,
.surface-card-inner,
.question-form,
.analysis-stack,
.chat-thread,
.record-cue-archive,
.record-transcript-list,
.dimension-list,
.records-list,
.question-groups,
.resume-nav-list,
.resume-module-summary-list,
.candidate-upload-list,
.setup-form {
  display: grid;
  gap: 16px;
}

.desktop-page {
  gap: 20px;
}

.desktop-page-header {
  align-items: center;
}

.desktop-page-title {
  gap: 6px;
}

.page-eyebrow,
.subtle-label,
.field-label,
.filter-label,
.position-summary-label {
  color: var(--subtle);
  font-size: 12px;
  line-height: 1.5;
}

.desktop-page-title h1,
.surface-card h2,
.empty-card h2,
.drawer-header h2,
.dialog-panel h2,
.question-bank-row-head strong,
.resume-module-summary strong {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.5;
}

.page-hero-copy p,
.surface-card p,
.empty-card p,
.inline-message,
.dialog-copy,
.records-list-item p,
.chat-bubble p,
.analysis-panel li,
.simple-list li,
.candidate-upload-item p,
.candidate-upload-item small,
.resume-module-summary p,
.question-tab span,
.position-summary-score span {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.6;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid transparent;
  border-radius: var(--radius-control);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  transition:
    transform 160ms ease,
    background-color 160ms ease,
    border-color 160ms ease,
    color 160ms ease,
    box-shadow 160ms ease;
}

.button:hover,
.button:focus-visible,
.mini-link:hover,
.mini-link:focus-visible,
.position-summary-card:hover,
.position-summary-card:focus-visible,
.records-list-item:hover,
.records-list-item:focus-visible,
.question-bank-row-head:hover,
.question-bank-row-head:focus-visible,
.resume-module-summary:hover,
.resume-module-summary:focus-visible,
.resume-nav-item:hover,
.resume-nav-item:focus-visible,
.question-tab:hover,
.question-tab:focus-visible {
  outline: none;
  transform: translateY(-1px);
}

.button:active,
.mini-link:active {
  transform: translateY(0);
}

.button.primary {
  color: #fff;
  background: linear-gradient(180deg, var(--accent), var(--accent-strong));
  box-shadow: 0 10px 22px rgb(33 93 143 / 0.18);
}

.button.secondary,
.mini-link,
.compact-select {
  border-color: var(--line);
  background: #fff;
}

.button.ghost {
  color: var(--muted);
}

.button.danger {
  color: #fff;
  background: var(--danger);
}

.compact-button {
  min-height: 36px;
  padding-inline: 14px;
}

.voice-main-button {
  width: fit-content;
  min-width: 140px;
}

.hero-actions,
.drawer-actions,
.cta-row,
.launch-bar-actions,
.voice-dock-group,
.filter-controls,
.pill-row,
.question-bank-head,
.question-tab-row,
.quiet-toggle-group {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.quiet-toggle-group {
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: #f7fafc;
}

.quiet-toggle {
  min-height: 32px;
  padding: 0 12px;
  border-radius: 10px;
  color: var(--muted);
}

.quiet-toggle.active {
  color: var(--ink);
  background: #fff;
  box-shadow: 0 8px 18px rgb(17 24 39 / 0.08);
}

.input,
.textarea,
select.input,
.chat-composer textarea,
.drawer-form textarea {
  width: 100%;
  min-height: 42px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-control);
  background: #fff;
  color: var(--ink);
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background-color 160ms ease;
}

.input:focus,
.textarea:focus,
select.input:focus,
.chat-composer textarea:focus,
.drawer-form textarea:focus {
  outline: none;
  border-color: rgb(94 138 179 / 0.9);
  box-shadow: 0 0 0 4px rgb(33 93 143 / 0.12);
}

.textarea {
  min-height: 132px;
  resize: vertical;
}

.textarea.compact {
  min-height: 96px;
}

.textarea.tall {
  min-height: 220px;
}

.surface-card,
.empty-card,
.position-summary-card,
.records-list-item,
.question-bank-row,
.candidate-upload-item,
.record-cue-item,
.dimension-item,
.record-transcript-item,
.upload-dropzone,
.analysis-collapse,
.analysis-panel,
.recognized-box,
.launch-bar,
.keyword-strip {
  border: 1px solid var(--line);
  border-radius: var(--radius-card);
  background: rgb(255 255 255 / 0.94);
  box-shadow: var(--shadow-soft);
}

.surface-card-inner,
.empty-card,
.launch-bar,
.record-cue-item,
.dimension-item,
.record-transcript-item,
.candidate-upload-item,
.analysis-panel {
  padding: 22px;
}

.surface-card-inner {
  gap: 18px;
}

.empty-card.compact {
  padding: 20px;
}

.position-board,
.cockpit-layout,
.page-grid,
.record-detail-grid,
.mock-room-layout,
.resume-layout,
.two-column-layout {
  display: grid;
  gap: 16px;
}

.position-board {
  grid-template-columns: 1fr;
}

.position-summary-card {
  display: grid;
  grid-template-columns: 4px minmax(0, 1fr);
  padding: 0;
  color: inherit;
  text-align: left;
  overflow: hidden;
}

.position-summary-rail {
  background: transparent;
}

.position-summary-card.active {
  border-color: #c7d7e9;
  background: linear-gradient(180deg, #f6f9fc, #edf4fb);
}

.position-summary-card.active .position-summary-rail {
  background: var(--accent);
}

.position-summary-main {
  display: grid;
  gap: 14px;
  padding: 18px 20px;
}

.position-summary-head {
  align-items: center;
}

.position-summary-score {
  align-items: flex-end;
  flex-direction: column;
}

.position-summary-score strong {
  color: var(--accent);
  font-size: 22px;
  font-weight: 600;
  line-height: 1.2;
}

.position-progress-track,
.score-track,
.mock-progress-bar-line {
  height: 6px;
  border-radius: 999px;
  background: #edf1f4;
  overflow: hidden;
}

.position-progress-track span,
.score-track span,
.mock-progress-bar-line span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--accent), #4b85b7);
}

.launch-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.launch-bar-copy {
  display: grid;
  gap: 4px;
}

.desktop-topbar {
  padding: 14px 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgb(255 255 255 / 0.94);
}

.desktop-topbar-main,
.desktop-topbar-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.desktop-topbar-main strong,
.desktop-topbar-meta span {
  font-size: 14px;
  font-weight: 500;
}

.live-dot {
  position: relative;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #c4cad1;
}

.live-dot::before {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 1px solid transparent;
}

.live-dot.active {
  background: #2e7d32;
}

.live-dot.active::before {
  border-color: rgb(46 125 50 / 0.25);
}

.cockpit-layout {
  grid-template-columns: minmax(0, 1.02fr) minmax(320px, 0.98fr);
}

.recognized-box {
  display: grid;
  gap: 8px;
  padding: 14px 16px;
  background: #f8fafc;
}

.recognized-interim {
  color: #8a9098;
}

.recognized-final {
  color: var(--ink);
}

.recognized-placeholder {
  color: var(--subtle);
}

.keyword-strip {
  padding: 16px 18px;
}

.keyword-strip summary,
.analysis-collapse summary,
.keyword-inline-expand summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  cursor: pointer;
  list-style: none;
}

.keyword-strip summary::-webkit-details-marker,
.analysis-collapse summary::-webkit-details-marker,
.keyword-inline-expand summary::-webkit-details-marker {
  display: none;
}

.analysis-collapse {
  padding: 16px 18px;
}

.analysis-collapse[open] ul,
.keyword-inline-expand[open] .pill-row {
  margin-top: 12px;
}

.analysis-collapse ul,
.simple-list,
.record-transcript-list,
.record-cue-archive {
  margin: 0;
  padding: 0;
  list-style: none;
}

.simple-list li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.question-page-grid {
  grid-template-columns: minmax(320px, 0.9fr) minmax(0, 1.1fr);
  align-items: start;
}

.question-tab-row {
  border-bottom: 1px solid var(--line);
  padding-bottom: 6px;
}

.question-tab {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  padding: 0 0 10px;
  border: 0;
  border-bottom: 2px solid transparent;
  color: var(--muted);
  background: transparent;
}

.question-tab.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.question-bank-row {
  overflow: hidden;
}

.question-bank-row.expanded {
  border-color: #c7d7e9;
}

.question-bank-row-head {
  width: 100%;
  padding: 16px 18px;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
}

.question-bank-row-body {
  display: grid;
  gap: 12px;
  padding: 0 18px 18px;
}

.chat-thread {
  align-content: start;
  max-height: 520px;
  overflow: auto;
}

.chat-bubble {
  max-width: min(100%, 560px);
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #f7f9fb;
}

.chat-bubble.user {
  justify-self: end;
  background: #edf4fb;
}

.chat-composer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
}

.assistant-badge,
.status-chip,
.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 24px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 12px;
  line-height: 1.6;
}

.assistant-badge,
.status-chip {
  background: var(--accent-soft);
  color: var(--accent);
}

.status-chip.positive {
  background: var(--success-soft);
  color: var(--success-ink);
}

.status-chip.warn {
  background: var(--warn-soft);
  color: var(--warn-ink);
}

.status-chip.muted,
.pill {
  background: #f2f5f8;
  color: #35536d;
}

.upload-dropzone {
  position: relative;
  display: grid;
  justify-items: start;
  gap: 8px;
  padding: 18px;
  cursor: pointer;
  background: linear-gradient(180deg, #fbfcfd, #f6f9fc);
}

.upload-dropzone.compact {
  padding: 16px;
}

.upload-dropzone input,
.file-button input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}

.inline-message {
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: #f7f9fb;
}

.inline-message.success {
  border-color: #cfe3d4;
  background: #f2faf4;
  color: #235c38;
}

.inline-message.error {
  border-color: #efc9c4;
  background: #fff6f5;
  color: #8b251f;
}

.mock-room-layout {
  grid-template-columns: minmax(0, 1.2fr) 340px;
}

.mock-main-column,
.mock-side-column,
.jd-analysis-column {
  display: grid;
  gap: 16px;
  align-content: start;
}

.simplified-voice-dock,
.voice-dock {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgb(255 255 255 / 0.96);
  box-shadow: var(--shadow-soft);
}

.resume-layout {
  grid-template-columns: 148px minmax(0, 1fr) 240px;
  align-items: start;
}

.resume-nav-column,
.resume-ai-column {
  position: sticky;
  top: 24px;
}

.resume-nav-item,
.resume-module-summary {
  display: grid;
  gap: 4px;
  width: 100%;
  padding: 12px;
  border: 1px solid transparent;
  border-radius: var(--radius-control);
  color: inherit;
  background: transparent;
  text-align: left;
}

.resume-nav-item {
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 10px;
  min-height: 42px;
  color: var(--muted);
}

.resume-nav-item.active,
.resume-module-summary.active {
  border-color: #c7d7e9;
  background: #f5f9fd;
}

.resume-module-summary-list {
  grid-template-columns: 1fr;
}

.resume-module-summary p {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.resume-profile-head {
  padding-bottom: 14px;
  border-bottom: 1px solid #edf1f4;
}

.resume-avatar {
  width: 54px;
  height: 54px;
  border-radius: 18px;
  color: #fff;
  background: linear-gradient(180deg, var(--accent), var(--accent-strong));
  font-size: 20px;
  font-weight: 600;
}

.resume-chat-thread {
  max-height: 460px;
}

.records-list-item {
  width: 100%;
  padding: 18px 20px;
  color: inherit;
  text-align: left;
}

.records-list-main,
.records-list-side,
.summary-copy,
.summary-score {
  display: grid;
  gap: 8px;
}

.records-list-side {
  justify-items: end;
  align-self: center;
  color: var(--muted);
}

.summary-strip {
  align-items: center;
}

.summary-score strong {
  color: var(--accent);
  font-size: 34px;
  line-height: 1;
}

.record-detail-grid,
.page-grid,
.two-column-layout {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.transcript-panel {
  grid-column: 1 / -1;
}

.record-transcript-item {
  max-width: min(100%, 780px);
  background: #f8fafc;
}

.record-transcript-item.candidate {
  justify-self: end;
  background: #edf4fb;
}

.metrics-grid.compact {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.metric-card {
  display: grid;
  gap: 8px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #fbfcfd;
}

.metric-card span,
.metric-card p,
.metric-card small {
  color: var(--muted);
}

.metric-card strong {
  font-size: 28px;
  line-height: 1;
}

.candidate-upload-item strong,
.record-cue-item strong,
.dimension-item strong {
  font-size: 15px;
  font-weight: 600;
}

.setup-form {
  grid-template-columns: 1fr;
}

.setup-form label {
  display: grid;
  gap: 8px;
}

.compact-filter-bar {
  align-items: center;
}

.compact-filter-controls {
  justify-content: flex-end;
}

.compact-select {
  width: auto;
  min-width: 180px;
}

.keyword-inline-expand {
  margin-top: 10px;
}

.dialog-copy {
  margin-top: -4px;
}

.skeleton-line,
.skeleton-box {
  border-radius: 12px;
  background: linear-gradient(90deg, #eef2f5 0%, #f7fafc 50%, #eef2f5 100%);
  background-size: 200% 100%;
  animation: cardSkeleton 1.2s ease infinite;
}

.skeleton-line {
  height: 16px;
}

.skeleton-line.wide {
  width: 62%;
}

.skeleton-box {
  height: 56px;
}

@keyframes cardSkeleton {
  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }
}

@media (max-width: 1180px) {
  .cockpit-layout,
  .question-page-grid,
  .mock-room-layout,
  .resume-layout,
  .record-detail-grid,
  .page-grid,
  .two-column-layout {
    grid-template-columns: 1fr;
  }

  .resume-nav-column,
  .resume-ai-column {
    position: static;
  }
}

@media (max-width: 900px) {
  .app-shell-v3 {
    display: block;
  }

  .main-v3 {
    padding: 20px 16px 24px;
  }
}

@media (max-width: 760px) {
  .desktop-page-header,
  .desktop-topbar,
  .section-row-header,
  .launch-bar,
  .voice-dock,
  .summary-strip,
  .filter-bar,
  .records-list-item,
  .position-summary-head,
  .question-bank-row-head {
    flex-direction: column;
    align-items: flex-start;
  }

  .surface-card-inner,
  .empty-card,
  .drawer-panel,
  .dialog-panel,
  .mobile-drawer,
  .record-cue-item,
  .dimension-item,
  .record-transcript-item {
    padding: 18px;
  }

  .hero-actions,
  .drawer-actions,
  .cta-row,
  .launch-bar-actions,
  .voice-dock-group,
  .filter-controls,
  .chat-composer {
    flex-direction: column;
    align-items: stretch;
  }

  .chat-composer {
    grid-template-columns: 1fr;
  }

  .button,
  .mini-link,
  .compact-select {
    width: 100%;
  }
}

