import { act, render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, describe, expect, it, vi } from "vitest";
import { App } from "./App";
import type { InterviewRecord } from "./types";
import { createPosition, createProfile } from "./lib/interviewEngine";

type SpeechRecognitionMock = {
  start: ReturnType<typeof vi.fn>;
  stop: ReturnType<typeof vi.fn>;
  abort: ReturnType<typeof vi.fn>;
  onresult: ((event: { resultIndex: number; results: ArrayLike<{ isFinal: boolean; 0: { transcript: string } }> }) => void) | null;
  onerror: ((event: { error: string }) => void) | null;
  onend: (() => void) | null;
};

let lastRecognition: SpeechRecognitionMock | null = null;

function installSpeechRecognitionMock() {
  function MockSpeechRecognition() {
    const instance: SpeechRecognitionMock = {
      start: vi.fn(),
      stop: vi.fn(),
      abort: vi.fn(),
      onresult: null,
      onerror: null,
      onend: null,
    };
    instance.stop.mockImplementation(() => instance.onend?.());
    lastRecognition = instance;
    return instance;
  }
  Object.defineProperty(window, "SpeechRecognition", { configurable: true, value: MockSpeechRecognition });
}

function emitSpeech(text: string, isFinal: boolean) {
  const result = { isFinal, 0: { transcript: text }, length: 1, item: () => ({ transcript: text }) };
  const results = Object.assign([result], { item: () => result });
  act(() => lastRecognition?.onresult?.({ resultIndex: 0, results }));
}

function mockJsonResponse(data: unknown) {
  return Promise.resolve({ ok: true, json: () => Promise.resolve(data) } as Response);
}

function mockCueCardStream(questionText = "请介绍一个你做过的增长项目") {
  const encoder = new TextEncoder();
  const card = {
    id: "card-server",
    questionText,
    createdAt: new Date().toISOString(),
    source: "live",
    strategy: "先给结论，再讲动作和结果。",
    openingLine: "我想从一个增长项目讲起。",
    bullets: ["背景", "动作", "结果"],
    evidenceIds: ["project-growth"],
    risks: ["不要泛泛而谈"],
    followUps: ["你怎么验证效果？"],
  };
  const stream = new ReadableStream({
    start(controller) {
      controller.enqueue(
        encoder.encode(
          `event: card\ndata: ${JSON.stringify({
            card,
            promptRun: { status: "success", latencyMs: 874 },
            searchCount: 0,
            meta: { backendStatus: "success", fallbackReason: "", evidenceTrace: [], latencyMs: 874 },
          })}\n\n`,
        ),
      );
      controller.close();
    },
  });
  return Promise.resolve({ ok: true, body: stream } as Response);
}

afterEach(() => {
  vi.restoreAllMocks();
  lastRecognition = null;
  window.localStorage.clear();
  window.history.replaceState({}, "", "/");
  Reflect.deleteProperty(window, "SpeechRecognition");
});

function renderApp(route = "/") {
  window.history.replaceState({}, "", route);
  render(<App />);
}

describe("App", () => {
  it("uses the seven-route navigation without the removed legacy entry", () => {
    renderApp();
    const nav = within(screen.getByLabelText("主导航"));

    ["岗位台", "实时助手", "模拟面试", "JD 分析", "问题库", "简历", "记录复盘"].forEach((name) => {
      expect(nav.getByRole("button", { name })).toBeInTheDocument();
    });
    expect(nav.queryByRole("button", { name: "上下文资料" })).not.toBeInTheDocument();
  });

  it("shows the simplified home without the removed explanatory hero or shortcuts", async () => {
    const user = userEvent.setup();
    renderApp();

    expect(screen.getByRole("heading", { name: "我的岗位" })).toBeInTheDocument();
    expect(screen.queryByRole("heading", { name: "选择一个岗位，直接进入面试准备" })).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "JD 分析" })).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "问题库" })).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "简历" })).not.toBeInTheDocument();

    await user.click(screen.getByRole("button", { name: "新增岗位" }));
    const dialog = screen.getByRole("dialog", { name: "新增岗位抽屉" });
    expect(within(dialog).getByRole("heading", { name: "粘贴 JD 文本" })).toBeInTheDocument();

    await user.clear(within(dialog).getByLabelText("JD 文本"));
    await user.type(
      within(dialog).getByLabelText("JD 文本"),
      "岗位：高级产品经理\n公司：腾讯\n职责：负责增长产品与数据分析，推动跨团队协作与商业化落地",
    );
    await user.click(within(dialog).getByRole("button", { name: "生成岗位卡" }));

    await waitFor(() => expect(screen.queryByRole("dialog", { name: "新增岗位抽屉" })).not.toBeInTheDocument());
    expect(screen.getByRole("button", { name: /腾讯 · 高级产品经理/ })).toBeInTheDocument();
    expect(screen.getByText("简历匹配度")).toBeInTheDocument();
  });

  it("keeps live speech text after stop, lets the user edit, and generates a cue card without exposing removed labels", async () => {
    installSpeechRecognitionMock();
    vi.spyOn(window, "fetch").mockImplementation((input) => {
      if (String(input).includes("/api/copilot/cue-card/stream")) return mockCueCardStream("请介绍一个你做过最有挑战性的产品功能");
      return mockJsonResponse({});
    });
    const user = userEvent.setup();
    renderApp("/live");

    expect(screen.getByText(/实时助手 ·/)).toBeInTheDocument();
    expect(screen.queryByText("interim / final")).not.toBeInTheDocument();
    expect(screen.queryByText("可编辑文本")).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "查看 JD 摘要" })).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "去模拟练习" })).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "去 JD 分析" })).not.toBeInTheDocument();

    await user.click(screen.getByRole("button", { name: "开始听取" }));
    emitSpeech("请介绍一个", false);
    expect(screen.getByText("请介绍一个")).toBeInTheDocument();
    emitSpeech("请介绍一个你做过最有挑战性的产品功能", true);
    await user.click(screen.getByRole("button", { name: "停止听取" }));

    const textarea = screen.getByLabelText("实时问题输入") as HTMLTextAreaElement;
    expect(textarea.value).toContain("请介绍一个你做过最有挑战性的产品功能");

    await user.type(textarea, "，重点说数据验证");
    await user.click(screen.getByRole("button", { name: /生成提词卡/ }));

    await waitFor(() => expect(screen.getByText("提词卡")).toBeInTheDocument());
    expect(screen.getAllByText(/模型/).length).toBeGreaterThan(0);
    expect(screen.getByText("风险提醒")).toBeInTheDocument();
    expect(screen.getByText("追问预测")).toBeInTheDocument();
    expect((screen.getByLabelText("实时问题输入") as HTMLTextAreaElement).value).toContain("重点说数据验证");

    await user.click(screen.getByRole("button", { name: "结束" }));
    expect(screen.getByRole("dialog", { name: "结束实时助手" })).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "保存记录" })).not.toBeInTheDocument();
  });

  it("auto-generates a live cue card from final speech text", async () => {
    installSpeechRecognitionMock();
    vi.spyOn(window, "fetch").mockImplementation((input) => {
      if (String(input).includes("/api/copilot/cue-card/stream")) return mockCueCardStream();
      return mockJsonResponse({});
    });
    const user = userEvent.setup();
    renderApp("/live");

    await user.click(screen.getByRole("button", { name: "自动生成" }));
    await user.click(screen.getByRole("button", { name: "开始听取" }));
    emitSpeech("请介绍一个你做过的增长项目", true);
    act(() => lastRecognition?.onend?.());

    await waitFor(() => expect(screen.getByRole("button", { name: "沉淀到问题库" })).toBeInTheDocument(), { timeout: 2500 });
  });

  it("uses the mock interview backend path, keeps the in-room UI minimal, and saves a mock report", async () => {
    vi.spyOn(window, "fetch").mockImplementation((input) => {
      const url = String(input);
      if (url.includes("/api/mock/session") && !url.includes("/answer")) {
        return mockJsonResponse({
          sessionId: "session-test",
          question: "请讲一个你做过的增长项目。",
          backendStatus: "success",
          questionSource: "模型出题",
        });
      }
      if (url.includes("/api/mock/session/session-test/answer")) {
        return mockJsonResponse({
          backendStatus: "success",
          followUp: "你怎么判断这个增长动作不是短期补贴带来的？",
          record: {
            id: "server-record",
            report: {
              overallScore: 82,
              dimensions: {
                completeness: 80,
                relevance: 84,
                evidenceStrength: 79,
                structure: 83,
                riskControl: 78,
              },
              summary: "回答完整，但证据还能更具体。",
              nextActions: ["补充更可验证的结果数据"],
            },
          } as InterviewRecord,
          decision: { type: "followup", question: "追问", instantFeedback: "结构清晰，但证据还能更具体。", internalNote: "" },
        });
