    const startDialog = await screen.findByRole("dialog", { name: "开始模拟面试" });
    await user.click(within(startDialog).getByRole("button", { name: "开始" }));

    await waitFor(() => expect(screen.getAllByText("请讲一个你做过的增长项目。").length).toBeGreaterThan(0));
    expect(screen.queryByText("当前均分")).not.toBeInTheDocument();
    expect(screen.queryByText("连续高分")).not.toBeInTheDocument();
    expect(screen.queryByText("已答")).not.toBeInTheDocument();
    expect(screen.queryByText("练习风格")).not.toBeInTheDocument();
    expect(screen.queryByText("面试官风格")).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "朗读" })).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "暂停" })).not.toBeInTheDocument();
