import { ArrowRight, FileText, Upload } from "lucide-react";
import { ChangeEvent, FormEvent, useMemo, useState } from "react";
import { repairText } from "../lib/copy";
import { importResumeFile } from "../lib/resumeImport";
import type { CandidateProfile, EvidenceItem, Position } from "../types";
import { buildResumeSections, buildResumeSuggestion, makeId, resolveEvidenceType, sectionsToDrafts, type ResumeChatMessage, type ResumeSectionId } from "./shared";

export function ResumeWorkspacePage({
  profile,
  position,
  onUpdateResume,
  onUpdateEvidence,
  onSetHighlights,
  onOpenLive,
  onOpenJd,
}: {
  profile: CandidateProfile;
  position?: Position;
  onUpdateResume: (resumeText: string) => void;
  onUpdateEvidence: (items: EvidenceItem[]) => void;
  onSetHighlights: (highlights: string[]) => void;
  onOpenLive: () => void;
  onOpenJd: () => void;
}) {
  const sections = useMemo(() => buildResumeSections(profile), [profile]);
  const [selectedSectionId, setSelectedSectionId] = useState<ResumeSectionId>("highlights");
  const initialDrafts = useMemo(() => sectionsToDrafts(sections), [sections]);
  const [draftOverrides, setDraftOverrides] = useState<Partial<Record<ResumeSectionId, string>>>({});
  const [chatInput, setChatInput] = useState("");
  const [fileMessage, setFileMessage] = useState("");
  const [chatMessages, setChatMessages] = useState<ResumeChatMessage[]>([
    { id: "resume-chat-1", role: "assistant", text: "閫変腑宸︿晶浠讳竴妯″潡锛屾垜鍙互甯綘娑﹁壊銆佹敼鍐欍€佹彁鐐间寒鐐癸紝鎴栨寜褰撳墠宀椾綅缁欏嚭鍖归厤寤鸿銆? },
  ]);

  const selectedSection = sections.find((section) => section.id === selectedSectionId) ?? sections[0];
  const sectionDrafts = { ...initialDrafts, ...draftOverrides } as Record<ResumeSectionId, string>;

  const onFile = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const result = await importResumeFile(file);
      onUpdateResume(result.text);
      setFileMessage(`宸插鍏?${file.name}${result.warning ? `锛?{result.warning}` : ""}`);
    } catch {
      setFileMessage("瀵煎叆澶辫触锛屽綋鍓嶆敮鎸?txt / markdown / pdf / docx銆?);
    } finally {
      event.target.value = "";
    }
  };

  const saveSection = () => {
    const text = sectionDrafts[selectedSectionId].trim();
    if (!text) return;

    if (selectedSectionId === "highlights") {
      onSetHighlights(
        text
          .split(/\n+/)
          .map((item) => item.replace(/^[-\d.\s]+/, "").trim())
          .filter(Boolean)
          .slice(0, 6),
      );
      return;
    }

    onUpdateEvidence([
      {
        id: makeId("ev-custom"),
        type: resolveEvidenceType(selectedSectionId),
        title: selectedSection.title,
        detail: text,
        keywords: [],
        impact: "浠庣畝鍘嗛〉鎵嬪姩娌夋穩鐨勫彲澶嶇敤绱犳潗",
      },
      ...profile.evidenceLibrary,
    ]);
  };

  const optimizeSection = () => {
    const suggestion = buildResumeSuggestion(selectedSection.title, sectionDrafts[selectedSectionId] || selectedSection.content, profile);
    setChatMessages((current) => [
      ...current,
      { id: makeId("resume-user"), role: "user", text: `浼樺寲銆?{selectedSection.title}銆峘 },
      { id: makeId("resume-ai"), role: "assistant", text: "鎴戞暣鐞嗕簡涓€鐗堟洿閫傚悎鎶曢€掑拰闈㈣瘯琛ㄨ揪鐨勫啓娉曪紝浣犲彲浠ュ厛鐪嬪啀鍐冲畾鏄惁搴旂敤銆?, sectionId: selectedSectionId, suggestion },
    ]);
  };

  const sendChat = (event: FormEvent) => {
    event.preventDefault();
    const text = chatInput.trim();
    if (!text) return;
    const suggestion = buildResumeSuggestion(selectedSection.title, `${sectionDrafts[selectedSectionId]}\n${text}`, profile);
    setChatMessages((current) => [
      ...current,
      { id: makeId("resume-user"), role: "user", text },
      { id: makeId("resume-ai"), role: "assistant", text: "鎸変綘鐨勮姹傦紝鎴戠敓鎴愪簡涓€鐗堟洿鑱氱劍宀椾綅鍖归厤鍜岃〃杈剧粨鏋滅殑鐗堟湰銆?, sectionId: selectedSectionId, suggestion },
    ]);
    setChatInput("");
  };

  const applySuggestion = (message: ResumeChatMessage) => {
    if (!message.suggestion || !message.sectionId) return;
    setSelectedSectionId(message.sectionId);
    setSectionDrafts((current) => ({ ...current, [message.sectionId!]: message.suggestion! }));
  };

  return (
    <section className="page page-resume desktop-page">
      <header className="desktop-page-header">
        <div className="desktop-page-title">
          <span className="page-eyebrow">绠€鍘?/span>
          <h1>绠€鍘?/h1>
        </div>
        <div className="hero-actions">
          <button className="button secondary" type="button" onClick={onOpenJd}>
            JD 鍒嗘瀽
          </button>
          <button className="button primary" type="button" onClick={onOpenLive} disabled={!position}>
            寮€鍚疄鏃跺姪鎵?            <ArrowRight size={16} />
          </button>
        </div>
      </header>

      <div className="resume-layout focused-resume-layout">
        <aside className="surface-card resume-nav-column compact-nav-column">
          <div className="surface-card-inner">
            <div className="section-row-header">
              <div>
                <span className="subtle-label">妯″潡瀵艰埅</span>
                <h2>鎴戠殑绠€鍘?/h2>
              </div>
            </div>

            <div className="resume-nav-list">
              {sections.map((section) => (
                <button
                  key={section.id}
                  type="button"
                  className={selectedSectionId === section.id ? "resume-nav-item active" : "resume-nav-item"}
                  onClick={() => setSelectedSectionId(section.id)}
                >
                  <section.icon size={16} />
                  <span>{section.label}</span>
                </button>
              ))}
            </div>

            <label className="upload-dropzone compact">
              <Upload size={18} />
              <strong>涓婁紶绠€鍘?/strong>
              <p>鏀寔 Word / PDF锛屽鍏ュ悗浼氭洿鏂板綋鍓嶇畝鍘嗗唴瀹广€?/p>
